def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    points = [(r, c) for r in range(h) for c in range(w)
              if grid[r][c] != background]
    rmin = min(r for r, c in points)
    rmax = max(r for r, c in points)
    cmin = min(c for r, c in points)
    cmax = max(c for r, c in points)

    out = [row[:] for row in grid]

    def fill_row(r, left, right):
        for c in range(left, right + 1):
            if grid[r][c] == background:
                out[r][c] = 2

    def fill_col(c, top, bottom):
        for r in range(top, bottom + 1):
            if grid[r][c] == background:
                out[r][c] = 2

    fill_row(rmin, cmin, cmax)
    fill_row(rmax, cmin, cmax)
    fill_col(cmin, rmin, rmax)
    fill_col(cmax, rmin, rmax)

    for r in range(h):
        marks = [c for c in range(w) if grid[r][c] != background]
        if len(marks) >= 3:
            fill_row(r, marks[0], marks[-1])

    for c in range(w):
        marks = [r for r in range(h) if grid[r][c] != background]
        if len(marks) >= 3:
            fill_col(c, marks[0], marks[-1])

    return out
